#include <string>
using namespace std;

class Solution {
public:
    bool checkZeroOnes(string s) {
        int max1 = 0, max0 = 0, cur = 1;
        for (int i = 1; i < s.size(); ++i) {
            if (s[i] == s[i-1]) cur++;
            else cur = 1;
            if (s[i] == '1') max1 = max(max1, cur);
            else max0 = max(max0, cur);
        }
        if (s[0] == '1') max1 = max(max1, 1);
        else max0 = max(max0, 1);
        return max1 > max0;
    }
};
